/** What a meal saves (418 Shape): its head and its ingredients as foods or inline new foods, amounts only. */
export function mealPayload(value: Pick<LineSetValue, 'name' | 'notes' | 'image_path' | 'lines'>): NewMealWithIngredients {
    return {
        name: value.name.trim(),
        notes: value.notes,
        image_path: value.image_path,
        ingredients: value.lines.map((line: LineView) => {
            const { food_item_id, new_food_item, amount } = toLineInput(line);
            return { food_item_id, new_food_item, amount };
        }),
    };
}

/**
 * What Save changes on a meal that exists: the head fields that differ, and the ingredients only
 * when they do. Story 358: an edit made offline runs on a replica that may be behind the server, so
 * it says only what was changed here — a rename does not re-send a cover it never saw, nor
 * re-insert ingredients the server has since replaced.
 */
export function mealChanges(meal: MealWithIngredients, value: Pick<LineSetValue, 'name' | 'notes' | 'image_path' | 'lines'>): {
    head: { name?: string; notes?: string | null; image_path?: string | null };
    ingredients: NewMealWithIngredients['ingredients'] | null;
} {
    const next = mealPayload(value);
    const head: { name?: string; notes?: string | null; image_path?: string | null } = {};
    if (next.name !== meal.name) head.name = next.name;
    if ((next.notes ?? null) !== (meal.notes ?? null)) head.notes = next.notes ?? null;
    if ((next.image_path ?? null) !== (meal.image_path ?? null)) head.image_path = next.image_path ?? null;
    const same = next.ingredients.length === meal.ingredients.length
        && next.ingredients.every((i, n) => !i.new_food_item && i.food_item_id === meal.ingredients[n].food_item_id && i.amount === meal.ingredients[n].amount);
    return { head, ingredients: same ? null : next.ingredients };
}

/**
 * Story 423 — one meal of the library: `/health/meals/:id` edits it, `/health/meals/new` makes one,
 * both on `<line-set-editor mode=meal>` (name, notes, cover, ± on every ingredient, add, remove).
 * A new meal mints its id up front, so a cover picked offline is queued against the meal it
 * becomes (story 370). "Log it" opens the add-to-log flow on this meal.
 */
export class HealthMealEditScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private idValue: string | null = null;
    private readonly body = document.createElement('div');
    private readonly log = createComponentLogger('health-meal-edit-screen');
    private statusNodes = createScreenStatusNodes();
    private statusMixin = createScreenStatusMixin(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);

    setLoading(): void { this.statusMixin.setLoading(); }
    setError(err: unknown): void { this.statusMixin.setError(err); }
    clearStatus(): void { this.statusMixin.clearStatus(); }

    /** The meal to edit; null for a new one. */
    set mealId(value: string | null) { this.idValue = value; }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;
        const page = buildSectionPage(this, this.idValue ? 'Edit meal' : 'New meal', 'health', '/health/meals');
        this.body.className = 'log-edit';
        this.statusNodes.retryNode.addEventListener('click', () => void this.load());
        page.content.append(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode, this.body);
        void this.load();
    }

    /** Story 430: a new meal made of these logs (day order); Save makes them one log of it. */
    set fromLogs(value: string[]) { this.logIds = value; }
    private logIds: string[] = [];

    private async load(): Promise<void> {
        return safeExec(this, this.log, async () => {
            if (!this.idValue && this.logIds.length > 0) {
                const picked = await this.pickedLogs();
                this.render(null, picked);
                return;
            }
            this.render(this.idValue ? await HealthService.getMeal(this.idValue) : null);
        });
    }

    /**
     * Story 430 — the picked logs and their lines as a meal's: one line per food (418 #14), the
     * amounts summed, in day order. A line whose food was deleted has nothing to be an ingredient
     * of, so it is named and nothing is made.
     */
    private async pickedLogs(): Promise<{ logs: LogWithLines[]; lines: LineView[] }> {
        const logs = await Promise.all(this.logIds.map(async (id) => {
            const log = await HealthService.findLog(id);
            if (!log) throw new Error(`Log ${id} is gone — go back to the day and pick again.`);
            return log;
        }));
        const lines = logs.flatMap((l) => l.lines);
        const orphaned = lines.filter((l) => l.food_item_id === null).map((l) => l.food_name);
        if (orphaned.length > 0) throw new Error(`Cannot save as a meal: ${orphaned.join(', ')} no longer in the food library.`);
        const amounts = new Map<string, number>();
        for (const line of lines) amounts.set(line.food_item_id!, roundAmount((amounts.get(line.food_item_id!) ?? 0) + line.amount));
        const foods = await Promise.all([...amounts.keys()].map(async (foodId) => {
            const food = await HealthService.findFoodItem(foodId);
            if (!food) throw new Error(`Food ${foodId} not found.`);
            return food;
        }));
        return { logs, lines: foods.map((food) => foodLineView(food, amounts.get(food.id)!, uuidv7())) };
    }

    /** Story 430: the picked logs become one log of the new meal — first the log, then the old ones go. */
    private async mergeLogs(logs: LogWithLines[], meal: MealWithIngredients): Promise<string> {
        const first = logs[0];
        await HealthService.createLog({
            id: uuidv7(),
            date: first.date,
            meal_type: first.meal_type,
            consumed_at: first.consumed_at,
            meal_id: meal.id,
            name: meal.name,
            lines: meal.ingredients.map((i) => ({ food_item_id: i.food_item_id, amount: i.amount })),
        });
        for (const log of logs) await HealthService.deleteLog(log.id);
        return first.date;
    }

    private render(meal: MealWithIngredients | null, picked: { logs: LogWithLines[]; lines: LineView[] } | null = null): void {
        const id = meal?.id ?? uuidv7();
        const editor = document.createElement('line-set-editor') as LineSetEditor;
        editor.setAttribute('mode', 'meal');
        editor.setAttribute('name-required', '');
        if (meal) editor.setAttribute('deletable', '');
        customElements.upgrade(editor);
        editor.value = { name: meal?.name ?? '', notes: meal?.notes ?? null, image_path: meal?.image_path ?? null, id };
        editor.lines = meal ? meal.ingredients.map(ingredientView) : picked?.lines ?? [];

        const add = document.createElement('line-add-dialog') as LineAddDialog;
        editor.addEventListener(HEALTH_EVENTS.LINE_ADD_REQUEST, () => add.open(null));
        add.addEventListener(HEALTH_EVENTS.LINE_PICKED, (e: LinePickedEvent) => {
            editor.addLine(e.detail.line);
            void safeExec(this, this.log, () => bindPickedBarcode(e.detail.line, e.detail.bind));
        });
        editor.addEventListener(HEALTH_EVENTS.LINE_SET_SAVE, (e: LineSetSaveEvent) => {
            e.detail.respondWith = safeExec(this, this.log, async () => {
                if (!meal) {
                    const created = await HealthService.createMeal({ ...mealPayload(e.detail), id });
                    if (picked) {
                        const date = await this.mergeLogs(picked.logs, created);
                        goBack(`/health/day/${encodeURIComponent(date)}`);
                        return;
                    }
                } else {
                    const { head, ingredients } = mealChanges(meal, e.detail);
                    // New ingredients replace the list (PUT keeps notes and cover it is not sent);
                    // the head alone is a PATCH; nothing changed writes nothing.
                    if (ingredients) await HealthService.replaceMeal(meal.id, { ...head, name: head.name ?? meal.name, ingredients });
                    else if (Object.keys(head).length > 0) await HealthService.updateMealHead(meal.id, head);
                }
                goBack('/health/meals');
            });
        });
        editor.addEventListener(HEALTH_EVENTS.LINE_SET_DELETE, (e: LineSetDeleteEvent) => {
            if (!meal || !confirm(`Delete the meal “${meal.name}”? Logs made from it keep their name and lines.`)) return;
            e.detail.respondWith = safeExec(this, this.log, async () => {
                await HealthService.deleteMeal(meal.id);
                goBack('/health/meals');
            });
        });
        this.body.replaceChildren(editor, add);
        if (picked) {
            const note = document.createElement('p');
            note.className = 'from-logs-note';
            const n = picked.logs.length;
            note.textContent = `From ${n} log${n === 1 ? '' : 's'} on ${picked.logs[0].date} — saving makes ${n === 1 ? 'it' : 'them'} one log of this meal.`;
            this.body.prepend(note);
        }

        if (meal) {
            const logIt = document.createElement('button');
            logIt.type = 'button';
            logIt.className = 'edit-log-link';
            logIt.textContent = 'Log it…';
            logIt.addEventListener('click', () => navigate(`${addFoodPath()}?meal=${encodeURIComponent(meal.id)}`));
            this.body.append(logIt);
        }
    }
}

if (!customElements.get('health-meal-edit-screen')) {
    customElements.define('health-meal-edit-screen', HealthMealEditScreen);
}
